import{_ as r,l as s,o as e,c as n,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"泛型：单态化对擦除","description":"","frontmatter":{"title":"泛型：单态化对擦除","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/generics-monomorphization.md","filePath":"cs/generics-monomorphization.md","lastUpdated":1789023840000}'),h={name:"cs/generics-monomorphization.md"};function m(E,a,g,A,_,u){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="泛型-单态化对擦除" tabindex="-1">泛型：单态化对擦除 <a class="header-anchor" href="#泛型-单态化对擦除" aria-label="Permalink to &quot;泛型：单态化对擦除&quot;">​</a></h1><div class="epigraph"><p>同一套多态源，可以按类型参数复制出特化机器码，也可以擦掉参数只留一份代码。二者对身份、特化与二进制大小的答案相反。</p><footer>—— 据 Pierce TAPL 对 System F 的阐述；Bracha 等 Java 擦除设计；Rustonomicon / Appel 对特化的讨论整理</footer></div><p>上一课<a href="/cs/subtyping-variance">子类型与变型</a>允许 <code>List&lt;Dog&gt;</code> 与 <code>List&lt;Animal&gt;</code> 发生关系（或拒绝）。缺口是<strong>实现</strong>：编译器把 \\(\\forall\\) 或泛型类怎么降到无类型 IR。<a href="/cs/hindley-milner-w">算法 W</a> 的方案在表面；后端要单态化（C++/Rust）或擦除（Java）。本课钉权衡，不重写链接器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单态化：<code>id&lt;int&gt;</code> 与 <code>id&lt;string&gt;</code> 两份代码，可内联、可特化布局（<code>Vec&lt;u8&gt;</code> vs <code>Vec&lt;T&gt;</code>）。代价：代码膨胀、编译时间、弱身份（两个实例不是同一函数指针）。擦除：运行时 <code>List</code> 是一份，类型参数靠强制与桥接方法；不能特化原语布局（Java 的装箱）。缺口是<strong>这份降级选择</strong>，不是变型规则本身。</p><p>C# 的值类型有限特化、引用类型擦除，是中间点。点名即可。</p><h3 id="擦除不是「没有泛型」" tabindex="-1">擦除不是「没有泛型」 <a class="header-anchor" href="#擦除不是「没有泛型」" aria-label="Permalink to &quot;擦除不是「没有泛型」&quot;">​</a></h3><p>静态仍检查 <code>List&lt;String&gt;</code> 不能 <code>add(Integer)</code>。擦的是运行时的参数。反射看见的是 raw 或残缺信息——后课反射再接。</p><p><span class="marginnote">Java JSR-14 / Bracha 的擦除。System F 的类型抽象在语义上可擦（Reynolds 抽象）。Rust 单态化是实现策略。本课不把 JIT 的投机特化写完，运行时单元再谈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单态化：以「泛型函数+实参类型」为键克隆 IR，再进中端。共享：相同布局可合并（后课 ICF）。擦除：插入转换、桥接；变型用通配符在静态，运行时不变。</p>',11)),(e(),l(p,null,{default:o(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E6%B3%9B%E5%9E%8B%E6%BA%90%22%5D%20--%3E%20MONO%5B%22%E5%8D%95%E6%80%81%E5%8C%96%E5%85%8B%E9%9A%86%22%5D%0A%20%20GEN%20--%3E%20ER%5B%22%E6%93%A6%E9%99%A4%20%2B%20%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20MONO%20--%3E%20CODE%5B%22%E5%A4%9A%E4%BB%BD%E6%9C%BA%E5%99%A8%E7%A0%81%22%5D%0A%20%20ER%20--%3E%20ONE%5B%22%E4%B8%80%E4%BB%BD%E5%AD%97%E8%8A%82%E7%A0%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/inlining-heuristics">内联</a> 后课：单态化后的小函数更好内联；擦除后虚调用仍在。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份：<code>typeof(List&lt;int&gt;)</code> 在擦除语言里可能撞 <code>List&lt;string&gt;</code>。重载：擦除后签名冲突（<code>void f(List&lt;A&gt;)</code> 与 <code>void f(List&lt;B&gt;)</code>）是语言限制。单态化无此问题，但符号<a href="/cs/name-mangling">mangling</a> 变长。</p><p>不要用擦除语言的数组协变去「修」特化缺失。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写模板实例化的全部 SFINAE。后课默认：泛型有两条降路。下一课类型类：与隐式参数/字典传递，常在单态化语言里特化，在 Haskell 里传字典。</p><p>也不把 C 宏当泛型实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单态化换代码体积与特化；擦除换一份代码与装箱。</li><li>静态检查在两种实现上都要做。</li><li>运行时类型身份与重载因擦除而弱。</li><li>出处：Pierce TAPL；Bracha 等 Java 泛型；对照 Appel / Rust 特化实践。</li></ul>',9))])}const T=r(h,[["render",m]]);export{B as __pageData,T as default};
